package J04_ConditionalStatements;

public class MultipleStatements {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		if(true)
		{
			if(true)
			{
				System.out.println("abc");
			}
			else
			{
				System.out.println("xyz");
			}
		}
		else
		{
			System.out.println("none");
		}

	}

}
